const delay=ms=>new Promise(r=>setTimeout(r,ms));
function url(route,extra={}){const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);for(const[k,v]of Object.entries(extra))u.searchParams.set(k,String(v));return u.toString()}
async function nav(page,target){let err;for(let i=0;i<4;i++){try{const r=await page.goto(target,{waitUntil:'domcontentloaded',timeout:30000});const s=r?.status()||0;if(s===200){await delay(700);return s}err=new Error('HTTP '+s);if(![429,500,502,503,504].includes(s))break}catch(e){err=e}await delay(1800*(i+1))}throw err||new Error('navigation failed')}
