function errors(d){const e=[];if(!d.script)e.push('missing V3 script');if(d.ready!=='true')e.push('V3 not ready');if(!d.sidebarVisible)e.push('sidebar hidden');if(d.title!=='Refine Products')e.push('bad title');if(!d.sizeVisible||d.sizeInside)e.push('bad page-size placement');if(d.sizes.map(x=>x[0]).join(',')!=='50,100,250'||!d.sizes.find(x=>x[0]==='50')?.[1])e.push('bad page-size default');if(!d.info.length)e.push('no refine groups');for(const g of d.info){if(!g.inputs)e.push('group without checkboxes '+g.label);if(!g.checked&&g.open)e.push('inactive group open '+g.label);if(g.checked&&!g.open)e.push('active group closed '+g.label)}if(d.combined)e.push('combined Color/Pattern');if(d.oldVisible)e.push('old product surface visible');if(d.hiddenNavVisible)e.push('old navigation visible');if(!d.gridVisible)e.push('product grid hidden');if(d.gridVisible&&d.columns!==3)e.push('desktop product columns='+d.columns);if(d.position!=='sticky')e.push('sidebar not sticky');if(d.height<600)e.push('sidebar too short');if(!d.cards)e.push('no product cards');const h=d.root.split('/collections/')[1];if(d.structural.some(t=>!t.includes('/collections/')||!t.includes('sq_root='+encodeURIComponent(h))))e.push('bad structural target');if(d.native.some(n=>!n.startsWith('filter.')))e.push('bad native filter');return e}
async function toggle(page){const d=page.locator('.sq-refine-v3-group:not([open])').first();if(!await d.count())return true;const s=d.locator(':scope>summary'),a=await s.evaluate(el=>getComputedStyle(el,'::after').content);await s.click();await delay(80);const opened=await d.getAttribute('open')!==null,b=await s.evaluate(el=>getComputedStyle(el,'::after').content);await s.click();await delay(80);return /\+/.test(a)&&opened&&/[−\u2212-]/.test(b)&&await d.getAttribute('open')===null}
async function cardCount(page){return page.evaluate(()=>[...(document.querySelector('.product-grid')?.querySelectorAll(':scope>.product-grid__item')||[])].filter(x=>x.querySelector('a[href*="/products/"]')).length)}
